SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(p),'identity',to_jsonb(pg_identify_object('pg_proc'::regclass,p.oid,0)),'address',to_jsonb(pg_identify_object_as_address('pg_proc'::regclass,p.oid,0)),'owner',pg_get_userbyid(p.proowner),'language',to_jsonb(l),'kind',p.prokind,'support_oid',p.prosupport::oid,'arguments',pg_get_function_arguments(p.oid),'identity_arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'argument_types',(SELECT jsonb_agg(jsonb_build_object('position',x.position,'oid',x.oid,'identity',to_jsonb(pg_identify_object('pg_type'::regclass,x.oid,0))) ORDER BY x.position) FROM unnest(coalesce(p.proallargtypes,p.proargtypes::oid[])) WITH ORDINALITY x(oid,position)),'return_type',to_jsonb(pg_identify_object('pg_type'::regclass,p.prorettype,0)),'definition',CASE WHEN p.prokind IN ('f','p','w') THEN pg_get_functiondef(p.oid) END,'aggregate',to_jsonb(a)) ORDER BY p.oid),'[]'::jsonb) AS payload FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang LEFT JOIN pg_aggregate a ON a.aggfnoid=p.oid WHERE p.pronamespace='public'::regnamespace) AS capture